cat > /tmp/site.php <<'EOF'
<?php
echo "site uuid (db): " . \Drupal::config('system.site')->get('uuid') . PHP_EOL;
$storage = new \Drupal\Core\Config\FileStorage(\Drupal::root() . '/../config/sync');
$s = $storage->read('system.site');
echo "sync uuid: " . ($s['uuid'] ?? 'n/a') . PHP_EOL;
echo "sync default theme: " . (($storage->read('system.theme'))['default'] ?? 'n/a') . PHP_EOL;
echo "db default theme: " . \Drupal::config('system.theme')->get('default') . PHP_EOL;
EOF
cd /workspace && cp /tmp/site.php /workspace/site_tmp.php && su ddevuser -c "ddev drush php:script site_tmp.php" 2>&1 | tail -6; rm -f /workspace/site_tmp.php
